from collections import deque
# orbit under transpose and 31-reflections
out=[row[:] for row in grid]
unresolved=[]; mismatches=[]
for r in range(30):
 for c in range(30):
  if grid[r][c]!=6: continue
  seen={(r,c)}; q=[(r,c)]
  while q:
   a,b=q.pop()
   for x,y in [(b,a),(31-a,b),(a,31-b)]:
    if 0<=x<30 and 0<=y<30 and (x,y) not in seen: seen.add((x,y));q.append((x,y))
  vals={(grid[a][b],(a,b)) for a,b in seen if grid[a][b]!=6}
  if not vals: unresolved.append((r,c,sorted(seen)))
  else:
   v=next(iter(vals))[0]
   if any(v2!=v for v2,_ in vals): mismatches.append((r,c,vals))
   out[r][c]=v
len(unresolved),len(mismatches),len([(r,c) for r in range(30) for c in range(30) if grid[r][c]==6])
